question.solution:
def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        if ch not in counts:
            return False
        counts[ch] -= 1
        if counts[ch] < 0:
            return False
    return True

print(is_anagram('anagram', 'nagaram'))
print(is_anagram('rat', 'car'))
print(is_anagram('', ''))
